        b.author ? ` <span class="author">— ${esc(b.author)}</span>` : ""
      }</li>`
    )
    .join("")}</ul>`;
}

function homePage(books, error) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books.filter((b) => b.status === "finished");
  return layout(
    "My Books",
    `<h2>Currently reading (${reading.length})</h2>
${bookList(reading, "Nothing here yet — add a book below.")}
<h2>Finished (${finished.length})</h2>
${bookList(finished, "No finished books yet.")}
<form class="add" method="post" action="/books">
  <h2>Add a book</h2>
  ${error ? `<p class="error">${esc(error)}</p>` : ""}
  <label for="title">Title *</label>
  <input type="text" id="title" name="title" required>
  <label for="author">Author</label>
  <input type="text" id="author" name="author">
  <label for="notes">Notes</label>
  <textarea id="notes" name="notes" rows="3"></textarea>
  <button type="submit">Add book</button>
</form>`
  );
}

function bookPage(book, baseUrl) {
  const status =
    book.status === "finished"
      ? `<span class="badge">Finished ${esc(fmtDate(book.finishedAt))}</span>`
      : `<span class="badge">Reading</span>`;
  return layout(
    book.title,
    `<p><a href="/">← All books</a></p>
<h2 style="font-size:1.4rem">${esc(book.title)} ${status}</h2>
<p class="author">by ${esc(book.author) || "Unknown author"}</p>
<p class="meta">Added ${esc(fmtDate(book.addedAt))}</p>
<h3>Notes</h3>
<p class="notes">${book.notes ? esc(book.notes) : "<span class='empty'>No notes yet.</span>"}</p>
${
  book.status !== "finished"
    ? `<form method="post" action="/books/${esc(book.id)}/finish">
  <button type="submit">Mark as finished</button>
</form>`
    : ""
}
<h3>Share this book</h3>
<p class="share"><input type="text" readonly value="${esc(baseUrl + "/books/" + book.id)}" onclick="this.select()" aria-label="Link to this book"></p>`
  );
}

function notPage(message) {
  return layout("Not found", `<p>${esc(message)}</p><p><a href="/">← Back to all books</a></p>`);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1e6) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(body));
    req.on("error", reject);
  });
}

function send(res, status, html, headers = {}) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8", ...headers });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export async function handler(req, res) {
  const url = new URL(req.url, `http://${req.headers.host ?? "localhost"}`);
  const baseUrl = `http://${req.headers.host ?? `localhost:${PORT}`}`;
  const path = url.pathname;

  try {
    if (req.method === "GET" && path === "/") {
      return send(res, 200, homePage(await loadBooks()));
    }

    if (req.method === "POST" && path === "/books") {
      const fields = new URLSearchParams(await readBody(req));
      const title = (fields.get("title") ?? "").trim();
      if (!title) {
        return send(res, 400, homePage(await loadBooks(), "Title is required."));
      }
      const book = await addBook({
        title,
        author: fields.get("author"),
        notes: fields.get("notes"),
      });
      return redirect(res, `/books/${book.id}`);
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (bookMatch) {
      const id = decodeURIComponent(bookMatch[1]);
      if (req.method === "GET") {
        const book = await getBook(id);
        return book ? send(res, 200, bookPage(book, baseUrl)) : send(res, 404, notPage("No book with that link."));
      }
      if (req.method === "POST") {
        const book = await finishBook(id);
        return book ? redirect(res, `/books/${book.id}`) : send(res, 404, notPage("No book with that link."));
      }
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (finishMatch && req.method === "POST") {
      const book = await finishBook(decodeURIComponent(finishMatch[1]));
      return book ? redirect(res, `/books/${book.id}`) : send(res, 404, notPage("No book with that link."));
    }

    send(res, 404, notPage("Page not found."));
  } catch (err) {
    send(res, 500, layout("Error", "<p>Something went wrong.</p>"));
    console.error(err);
  }
}

export const server = http.createServer(handler);

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  server.listen(PORT, () => {
    console.log(`Book tracker running at http://localhost:${PORT}`);
  });
}

