import { describe, it, expect, beforeEach, afterAll } from "vitest";
import { mkdtemp, rm, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { newId, addBook, finishBook, getBook, loadBooks } from "./store.js";

let dir;

beforeEach(async () => {
  if (dir) await rm(dir, { recursive: true, force: true });
  dir = await mkdtemp(join(tmpdir(), "books-"));
  process.env.BOOKS_FILE = join(dir, "books.json");
});

afterAll(async () => {
  if (dir) await rm(dir, { recursive: true, force: true });
});

describe("store", () => {
  it("saves a book to the JSON file and reloads it", async () => {
    const book = await addBook({ title: "Dune", author: "Herbert", notes: "Good" });
    expect(book.status).toBe("reading");
    const raw = JSON.parse(await readFile(process.env.BOOKS_FILE, "utf8"));
    expect(raw).toHaveLength(1);
    const reloaded = await loadBooks();
    expect(reloaded[0].title).toBe("Dune");
  });

  it("marks a book as finished", async () => {
    const book = await addBook({ title: "Project Hail Mary" });
    const done = await finishBook(book.id);
    expect(done.status).toBe("finished");
    expect(done.finishedAt).toBeTruthy();
    expect((await getBook(book.id)).status).toBe("finished");
  });

  it("returns undefined for unknown ids", async () => {
    expect(await getBook("nope")).toBeUndefined();
    expect(await finishBook("nope")).toBeUndefined();
  });

  it("generates url-safe unique ids", () => {
    const ids = new Set(Array.from({ length: 100 }, newId));
    expect(ids.size).toBe(100);
    for (const id of ids) expect(id).toMatch(/^[A-Za-z0-9_-]+$/);
  });
});

