export function newId() {
  return randomBytes(6).toString("base64url");
}

export async function loadBooks() {
  try {
    const data = JSON.parse(await readFile(dataFile(), "utf8"));
    return Array.isArray(data) ? data : [];
  } catch (err) {
    if (err.code === "ENOENT" || err instanceof SyntaxError) return [];
    throw err;
  }
}

export async function saveBooks(books) {
  const file = dataFile();
  const tmp = `${file}.${process.pid}.tmp`;
  await writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await rename(tmp, file);
}

export async function getBook(id) {
  return (await loadBooks()).find((b) => b.id === id);
}

export async function addBook({ title, author, notes }) {
  const books = await loadBooks();
  const book = {
    id: newId(),
    title: title.trim(),
    author: (author ?? "").trim(),
    notes: (notes ?? "").trim(),
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await saveBooks(books);
  return book;
}

export async function finishBook(id) {
  const books = await loadBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return undefined;
  if (book.status !== "finished") {
    book.status = "finished";
    book.finishedAt = new Date().toISOString();
    await saveBooks(books);
  }
  return book;
}
